 "components/site/reviews.tsx": "\"use client\";\nimport { REVIEWS, RATING, type Review } from \"@/lib/reviews\";\nimport { Reveal } from \"@/components/site/page-kit\";\n\nconst D = \"font-[family-name:var(--font-display)]\";\n\nfunction Card({ r, className = \"\" }: { r: Review; className?: string }) {\n  const initials = r.name.replace(/[^A-Za-z ]/g, \"\").split(\" \").filter(Boolean).map((w) => w[0]).join(\"\").slice(0, 2).toUpperCase();\n  return (\n    <figure className={`${className} flex flex-col justify-between rounded-2xl border border-[#d6b25e]/20 bg-[#17234d] p-6`}>\n      <blockquote className=\"text-lg leading-snug text-[#f2ead8]\">{r.quote}</blockquote>\n      <figcaption className=\"mt-6 flex items-center gap-3 border-t border-[#f2ead8]/10 pt-5\">\n        <span className={`${D} grid h-11 w-11 shrink-0 place-items-center rounded-full bg-[#d6b25e] text-sm font-bold text-[#0b1330]`}>{initials}</span>\n        <span className={D}>\n          <b className=\"block text-base text-[#f2ead8]\">{r.name}</b>\n          <span className=\"text-sm text-[#f2ead8]/60\">{r.project}</span>\n        </span>\n      </figcaption>\n    </figure>\n  );\n}\n\n// Used on the Reviews page: all reviews in a grid.\nexport function ReviewCards() {\n  return (\n    <div className=\"grid gap-5 md:grid-cols-2 lg:grid-cols-3\">\n      {REVIEWS.map((r, i) => (\n        <Reveal key={r.name + i} delay={(i % 3) * 0.1} className=\"h-full\"><Card r={r} className=\"h-full\" /></Reveal>\n      ))}\n    </div>\n  );\n}\n\nfunction Row({ items, reverse = false }: { items: Review[]; reverse?: boolean }) {\n  const copies = Math.max(3, Math.ceil(8 / items.length));\n  return (\n    <div className=\"group overflow-hidden [mask-image:linear-gradient(to_right,transparent,black_8%,black_92%,transparent)]\">\n      <style>{`@keyframes hepta-marquee{to{transform:translateX(-${(100 / copies).toFixed(4)}%)}}`}</style>\n      <div className={`flex w-max py-2 [animation:hepta-marquee_80s_linear_infinite] group-hover:[animation-play-state:paused] motion-reduce:[animation:none] ${reverse ? \"[animation-direction:reverse]\" : \"\"}`}>\n        {Array.from({ length: copies }).flatMap((_, c) => items.map((r, i) => <Card key={`${c}-${i}`} r={r} className=\"mr-5 w-[320px] shrink-0 md:w-[400px]\" />))}\n      </div>\n    </div>\n  );\n}\n\n// Used on the home page: a few reviews as a grid, many reviews as a scrolling marquee.\nexport function Reviews() {\n  const half = Math.ceil(REVIEWS.length / 2);\n  return (\n    <section id=\"reviews\" className=\"scroll-mt-16 bg-[#0e1838] py-24\">\n      <div className=\"mx-auto mb-12 flex max-w-6xl flex-wrap items-end justify-between gap-6 px-5\">\n        <h2 className={`${D} text-4xl font-semibold tracking-tight md:text-6xl`}>What our clients say</h2>\n        {RATING && (\n          <div className={`${D} text-right`}>\n            <p className=\"text-3xl font-bold\">{RATING.score} <span className=\"text-base font-medium text-[#f2ead8]/60\">average</span></p>\n            <p className=\"text-sm text-[#f2ead8]/60\">from {RATING.count} completed projects</p>\n          </div>\n        )}\n      </div>\n      {REVIEWS.length < 6 ? (\n        <div className=\"mx-auto max-w-6xl px-5\"><ReviewCards /></div>\n      ) : (\n        <div className=\"space-y-5\">\n          <Row items={REVIEWS.slice(0, half)} />\n          <Row items={REVIEWS.slice(half)} reverse />\n        </div>\n      )}\n    </section>\n  );\n}\n",
 "app/process/page.tsx": "import type { Metadata } from \"next\";\nimport { PageHero, Reveal, Timeline, Cta } from \"@/components/site/page-kit\";\nimport { Process } from \"@/components/site/process\";\nimport { EXPECT, PAYMENT } from \"@/lib/pages\";\n\nexport const metadata: Metadata = { title: \"Process | Hepta Constructions & Interiors\" };\nconst D = \"font-[family-name:var(--font-display)]\";\n\nexport default function ProcessPage() {\n  return (\n    <main>\n      <PageHero eyebrow=\"Our process\" title=\"Clear stages, no surprises\" intro=\"Every project follows the same six stages. You sign off at each one before we move on.\" />\n      <Process />\n      <section className=\"bg-[#0e1838] py-20\">\n        <div className=\"mx-auto max-w-6xl px-5\">\n          <Reveal><h2 className={`${D} text-4xl font-semibold tracking-tight md:text-5xl`}>A typical 17-week project</h2></Reveal>\n          <p className=\"mb-10 mt-3 max-w-2xl text-[#f2ead8]/70\">Timelines vary with size and scope. You get a week-by-week schedule with your quote.</p>\n          <Timeline />\n        </div>\n      </section>\n      <section className=\"mx-auto max-w-6xl px-5 py-20\">\n        <Reveal><h2 className={`${D} text-4xl font-semibold tracking-tight md:text-5xl`}>What you can expect from us</h2></Reveal>\n        <div className=\"mt-10 grid gap-5 md:grid-cols-3\">\n          {EXPECT.map(([t, d], i) => (\n            <Reveal key={t} delay={(i % 3) * 0.1}><div className=\"h-full rounded-2xl border border-[#d6b25e]/20 bg-[#17234d] p-7\"><h3 className={`${D} text-2xl font-semibold`}>{t}</h3><p className=\"mt-3 text-[#f2ead8]/75\">{d}</p></div></Reveal>\n          ))}\n        </div>\n      </section>\n      <section className=\"bg-[#0e1838] py-20\">\n        <div className=\"mx-auto max-w-4xl px-5\">\n          <Reveal><h2 className={`${D} text-4xl font-semibold tracking-tight md:text-5xl`}>How payments work</h2></Reveal>\n          <p className=\"mb-8 mt-3 text-[#f2ead8]/70\">Payments are tied to progress, never paid all at once. The exact split is written into your contract.</p>\n          <div className=\"divide-y divide-[#f2ead8]/15 border-y border-[#f2ead8]/15\">\n            {PAYMENT.map(([s, p], i) => (\n              <Reveal key={s} delay={i * 0.06}><div className={`${D} flex items-center justify-between py-5 text-xl`}><span>{s}</span><b className=\"text-[#d6b25e]\">{p}</b></div></Reveal>\n            ))}\n          </div>\n        </div>\n      </section>\n      <Cta title=\"Ready for the first step?\" label=\"Book a site visit\" />\n    </main>\n  );\n}\n",
 "app/reviews/page.tsx": "import type { Metadata } from \"next\";\nimport { PageHero, Reveal, Count, Cta } from \"@/components/site/page-kit\";\nimport { ReviewCards } from \"@/components/site/reviews\";\nimport { RATING } from \"@/lib/reviews\";\n\nexport const metadata: Metadata = { title: \"Reviews | Hepta Constructions & Interiors\" };\nconst D = \"font-[family-name:var(--font-display)]\";\n\nexport default function Reviews() {\n  return (\n    <main>\n      <PageHero eyebrow=\"Reviews\" title=\"What our clients say about working with us\" intro=\"Feedback from the clients we have built and designed for.\" />\n      {RATING && (\n        <section className=\"mx-auto max-w-6xl px-5 pt-16\">\n          <Reveal>\n            <b className={`${D} block text-7xl font-extrabold`}><Count to={parseFloat(RATING.score)} decimals={1} /></b>\n            <p className=\"mt-2 text-[#f2ead8]/70\">Average rating from {RATING.count} completed projects</p>\n          </Reveal>\n        </section>\n      )}\n      <section className=\"mx-auto max-w-6xl px-5 py-16\"><ReviewCards /></section>\n      <Cta title=\"Join our happy clients\" />\n    </main>\n  );\n}\n",
