const bins = {"public/logo-full.png": "", "public/logo-header.png": "", "app/icon.png": ""};
for (const [f, c] of Object.entries(files)) {
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, c);
  console.log("wrote       ", f);
}
for (const [f, b64] of Object.entries(bins)) {
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, Buffer.from(b64, "base64"));
  console.log("wrote       ", f);
}

function edit(file, label, apply) {
  if (!fs.existsSync(file)) return console.log("MISSING      " + file);
  const r = apply(fs.readFileSync(file, "utf8"));
  if (r === "done") return console.log("already done ", label);
  if (r === null) return console.log("NOT FOUND    ", label);
  fs.writeFileSync(file, r);
  console.log("patched      ", label);
}
function swap(file, label, pairs) {
  edit(file, label, (s) => {
    let changed = false, found = 0;
    for (const [from, to] of pairs) {
      if (s.includes(from)) { s = s.split(from).join(to); changed = true; }
      else if (s.includes(to)) found++;
    }
    if (!changed) return found === pairs.length ? "done" : null;
    return s;
  });
}

// Company facts: 30+ projects, 9+ years of experience (started 2017)
swap("lib/content.ts", "company stats", [
  ['["120+", "Projects delivered"]', '["30+", "Projects delivered"]'],
  ['["12", "Years of practice"]', '["9+", "Years of experience"]'],
  ["Keys, warranties and 12 months of free fixes.", "Keys, warranties and all documents."],
]);
swap("components/site/stats.tsx", "stats note", [["Designing and building since 2014", "Designing and building since 2017"]]);

// Logo: header and footer use the reference logo
edit("components/site/chrome.tsx", "logo in header and footer", (s) => {
  if (s.includes("/logo-header.png")) return "done";
  const re = /export function Wordmark\([\s\S]*?\n}\n/;
  if (!re.test(s)) return null;
  const next = `export function Wordmark({ light }: { light?: boolean }) {
  void light;
  return <img src="/logo-header.png" alt="Hepta Constructions & Interiors" className="h-11 w-auto md:h-[52px]" />;
}

export function FullLogo() {
  return <img src="/logo-full.png" alt="Hepta Constructions & Interiors" className="h-28 w-auto md:h-32" />;
}
`;
  s = s.replace(re, () => next);
  s = s.replace(/<Wordmark light \/>(\s*)<div className="space-y-1">/, (m, ws) => "<FullLogo />" + ws + '<div className="space-y-1">');
  return s;
});
